import re

def _parse(v: str):
    v = v.split('+', 1)[0]
    parts = v.split('-', 1)
    main = [int(x) for x in parts[0].split('.')]
    prerelease = []
    if len(parts) > 1 and parts[1]:
        for p in parts[1].split('.'):
            if p.isdigit():
                prerelease.append((0, int(p)))
            else:
                prerelease.append((1, p))
    return main, prerelease

def compare_semver(v1: str, v2: str) -> int:
    m1, p1 = _parse(v1)
    m2, p2 = _parse(v2)
    if m1 != m2:
        return 1 if m1 > m2 else -1
    if not p1 and not p2:
        return 0
    if not p1 and p2:
        return 1 # normal > prerelease
    if p1 and not p2:
        return -1 # prerelease < normal
    if p1 == p2:
        return 0
    return 1 if p1 > p2 else -1
